@Service
public class CustomerUserDetailsService implements UserDetailsService {

    private final CustomerRepository customers;

    public CustomerUserDetailsService(CustomerRepository customers) {
        this.customers = customers;
    }

    @Override
    public UserDetails loadUserByUsername(String email) {
        return customers.findByEmail(email)
                .map(customer -> User.withUsername(customer.getEmail())
                        .password(customer.getPasswordHash())
                        .roles(customer.getRole().name())
                        .build())
                .orElseThrow(() -> new UsernameNotFoundException("No account for " + email));
    }
}

/** Throws BadCredentialsException (answered as 401) for an unknown email or a wrong password. */
public TokenResponse login(LoginRequest login) {
    Authentication account = authenticationManager.authenticate(
            UsernamePasswordAuthenticationToken.unauthenticated(login.email(), login.password()));
    return issueFor(account);
}

TokenResponse issueFor(Authentication account) {
    Instant now = Instant.now(clock);
    Duration ttl = shop.jwt().ttl();
    // Spring Security 7 also grants FACTOR_PASSWORD after a password login. Only roles go in the token.
    List<String> roles = account.getAuthorities().stream()
            .map(GrantedAuthority::getAuthority)
            .filter(authority -> authority.startsWith("ROLE_"))
            .sorted()
            .toList();
    JwtClaimsSet claims = JwtClaimsSet.builder()
            .issuer(JwtConfig.ISSUER)
            .subject(account.getName())
            .issuedAt(now)
            .expiresAt(now.plus(ttl))
            .claim("roles", roles)
            .build();
    JwsHeader header = JwsHeader.with(MacAlgorithm.HS256).build();
    String token = jwtEncoder.encode(JwtEncoderParameters.from(header, claims)).getTokenValue();
    return new TokenResponse(token, "Bearer", ttl.toSeconds());
}

/**
 * Who is calling, in the terms services care about: their email (the token's subject) and
 * whether they are an admin. Controllers build it from Spring Security's Authentication, so
 * services never read tokens or HTTP requests themselves.
 */
public record CurrentUser(String email, boolean admin) {

    public static CurrentUser of(Authentication authentication) {
        boolean admin = authentication.getAuthorities().stream()
                .anyMatch(authority -> "ROLE_ADMIN".equals(authority.getAuthority()));
        return new CurrentUser(authentication.getName(), admin);
    }
}

public OrderResponse get(long id, CurrentUser user) {
    return OrderResponse.from(requireVisible(id, user));
}

